scripts.script:
-- 🚀 SandMan's Era Of Supes GUI v2.0 | Feb 2026 FIXED | ALT ONLY + VPN/VM!
-- Switched to Rayfield UI (100% working, no addon errors)
-- Old Linoria had broken Addons links (capital A vs lowercase 'addons')

local Rayfield = loadstring(game:HttpGet('https://sirius.menu/rayfield'))()

-- Global toggle var
getgenv().EndRescueLoop = false
local EndRescueConnection = nil

local Window = Rayfield:CreateWindow({
   Name = "Sandman's Era Of Supes GUI ⚠️",
   LoadingTitle = "Loading Era Of Supes Tools...",
   LoadingSubtitle = "by Mr.Sandman",
   ConfigurationSaving = {
      Enabled = true,
      FolderName = "SandManHub",
      FileName = "v1.0"
   },
   Discord = {
      Enabled = false, -- Set true + paste Discord webhook for notifications
   },
   KeySystem = false -- Set true + paste Key link for key system
})

local MainTab = Window:CreateTab("Era Of Supes", nil) -- Roblox gun icon
local SectionAntiArrest = MainTab:CreateSection("Inf Stuff")
local SectionUtils = MainTab:CreateSection("⚙️ Utils")

-- One Shot AR Button
MainTab:CreateButton({
   Name = "Inf Stat Points Maybe",
   Callback = function()
      local args = {
         "Add",
         "AssaultRifleDamage",
         -100000000
      }
      pcall(function()
         game:GetService("ReplicatedStorage"):WaitForChild("Events"):WaitForChild("ChangeValue"):FireServer(unpack(args))
      end)
      Rayfield:Notify({
         Title = "Inf Stat Points Maybe",
         Content = "Should have in stat points",
         Duration = 3,
         Image = 4483362458 -- Gun icon
      })
   end,
})

-- EndRescue Spam Toggle
MainTab:CreateToggle({
   Name = "Inf Money And Levels",
   CurrentValue = false,
   Flag = "Inf STUFF",
   Callback = function(Value)
      getgenv().EndRescueLoop = Value
      if Value then
         EndRescueConnection = game:GetService("RunService").Heartbeat:Connect(function()
            if getgenv().EndRescueLoop then
               local args = { "EndRescue", {} }
               pcall(function()
                  game:GetService("ReplicatedStorage"):WaitForChild("Events"):WaitForChild("CrimeHandler"):FireServer(unpack(args))
               end)
            end
         end)
         Rayfield:Notify({
            Title = "Inf ACTIVE",
            Content = "Spamming EndRescue... (Toggle off to stop)",
            Duration = 2.5,
         })
      else
         if EndRescueConnection then
            EndRescueConnection:Disconnect()
            EndRescueConnection = nil
         end
         Rayfield:Notify({
            Title = "Inf STOPPED",
            Content = "Loop disconnected safely.",
            Duration = 2,
         })
      end
   end,
})

-- Rejoin Button
MainTab:CreateButton({
   Name = "🔄 Rejoin Server (Safe Reboot)",
   Callback = function()
      Rayfield:Notify({
         Title = "Rejoining...",
         Content = "Teleporting back to Da Hood.",
         Duration = 1.5,
      })
      game:GetService("TeleportService"):Teleport(game.PlaceId)
   end,
})

Rayfield:Notify({
   Title = "GUI LOADED! 🎉",
   Content = "Sections fixed - Rayfield UI",
   Duration = 6,
   Image = 4483362458
})
